import Foundation
import Testing
@testable import ParleyCore

// Native tool requests as the code before ReAct wrote them (Correction 8 of the ReAct design). The
// rows of `nativeToolGoldenBodies`, at the end of this file, were dumped from commit 6a1afc1 before
// any ReAct code existed. Do not regenerate them: they are the proof that a conversation in native
// mode sends what it always sent. `NoToolsGoldens` covers only the path without tools.
//
// A row is: case | server kind | stream_options | body. Bodies that carry `tools` go through
// `encodeBody`, whose sorted keys make the bytes stable, and are compared as bytes. The others have
// no stable key order between processes, so they are compared as sorted JSON, and
// `flattenedBodiesAreWrittenAsBefore` checks that `encodeBody` still writes them unsorted.

private let tools = [
    ChatTool(name: "srv__echo", description: "Echoes.\nSecond line, \"quoted\" </tag>.", parameters: .object([
        "type": .string("object"),
        "properties": .object(["text": .object(["type": .string("string"), "description": .string("What to echo.")])]),
        "required": .array([.string("text")]),
    ])),
    ChatTool(name: "srv__no_description", parameters: .object(["type": .string("object"), "properties": .object([:])])),
]

private func finishedCall(_ id: String, arguments: String = #"{"text":"hi"}"#, result: String = "hi") -> ToolCallRecord {
    ToolCallRecord(id: id, name: "srv__echo", arguments: arguments, serverName: "srv", toolName: "echo", startedAt: Date(),
                   result: ToolCallResult(status: .completed, text: result))
}

/// Two rounds: one with text and thinking and two calls, one without text whose calls were never
/// resolved or had malformed arguments. A result can hold anything a server sends.
private func rounds() -> [ToolRound] {
    [
        ToolRound(content: "Let me look.", reasoning: "never sent", calls: [
            finishedCall("call_1"),
            finishedCall("call_2", arguments: "  {\"text\": \"spaced\"}  ", result: "line 1\nline 2 \"quoted\" 世界"),
        ]),
        ToolRound(content: "", calls: [
            ToolCallRecord(id: "call_3", name: "srv__echo", arguments: "", serverName: "srv", toolName: "echo"),
            ToolCallRecord(id: "call_4", name: "srv__echo", arguments: #"{"text":"#, serverName: "srv", toolName: "echo", startedAt: Date()),
            ToolCallRecord(id: "call_5", name: "no_such_tool", arguments: "{}",
                           result: ToolCallResult(status: .notCalled, text: ToolResultText.unknownTool("no_such_tool"))),
            ToolCallRecord(id: "call_6", name: "srv__echo", arguments: "null", startedAt: Date(),
                           result: ToolCallResult(status: .completed, text: "")),
        ]),
    ]
}

private func reply(content: String) -> Message {
    var message = Message(role: .assistant, content: content, reasoning: "final thoughts")
    message.toolRounds = rounds()
    return message
}

/// A finished reply with rounds, a reply without any, then a question.
private func closedHistory() -> [Message] {
    [
        Message(role: .system, content: "history system"),
        Message(role: .user, content: "first"),
        reply(content: "Done."),
        Message(role: .assistant, content: "A plain reply."),
        Message(role: .user, content: "second"),
    ]
}

/// The reply in flight: finished rounds and no final text.
private func openHistory() -> [Message] {
    [Message(role: .user, content: "first"), reply(content: "")]
}

/// Empty `toolRounds`, which a file can hold, is a reply without rounds.
private func emptyRoundsHistory() -> [Message] {
    var message = Message(role: .assistant, content: "Plain.")
    message.toolRounds = []
    return [Message(role: .user, content: "first"), message, Message(role: .user, content: "second")]
}

private struct NativeGoldenCase {
    let name: String
    let systemPrompt: String
    let history: [Message]
    let tools: [ChatTool]?
    var omitsTools = false
    /// Sent through `encodeBody` with sorted keys, so the bytes themselves are the golden.
    var sendsTools: Bool { !omitsTools && !(tools ?? []).isEmpty }
}

private let nativeGoldenCases: [NativeGoldenCase] = [
    NativeGoldenCase(name: "tools", systemPrompt: " sys ", history: [Message(role: .user, content: "first")], tools: tools),
    NativeGoldenCase(name: "tools-no-system", systemPrompt: "", history: [Message(role: .user, content: "first")], tools: tools),
    NativeGoldenCase(name: "tools-blank-system", systemPrompt: "  \n", history: [Message(role: .user, content: "first")], tools: tools),
    NativeGoldenCase(name: "replay-closed", systemPrompt: " sys ", history: closedHistory(), tools: tools),
    NativeGoldenCase(name: "replay-closed-no-system", systemPrompt: "", history: closedHistory(), tools: tools),
    NativeGoldenCase(name: "replay-open", systemPrompt: " sys ", history: openHistory(), tools: tools),
    NativeGoldenCase(name: "replay-empty-rounds", systemPrompt: " sys ", history: emptyRoundsHistory(), tools: tools),
    NativeGoldenCase(name: "flattened-omitted", systemPrompt: " sys ", history: closedHistory(), tools: tools, omitsTools: true),
    NativeGoldenCase(name: "flattened-nil", systemPrompt: " sys ", history: closedHistory(), tools: nil),
    NativeGoldenCase(name: "flattened-empty", systemPrompt: "", history: closedHistory(), tools: []),
    NativeGoldenCase(name: "answer-now-cap", systemPrompt: " sys ", history: openHistory(), tools: tools, omitsTools: true),
    NativeGoldenCase(name: "answer-now-cap-no-system", systemPrompt: "", history: openHistory(), tools: tools, omitsTools: true),
    NativeGoldenCase(name: "answer-now-nil", systemPrompt: " sys ", history: openHistory(), tools: nil),
    NativeGoldenCase(name: "empty-rounds-flattened", systemPrompt: " sys ", history: emptyRoundsHistory(), tools: tools, omitsTools: true),
]

private let nativeGoldenKinds = ["nil", "lmStudio", "llamaCpp", "vLLM", "ollama", "strata", "hosted"]

private func options(for golden: NativeGoldenCase, kind: String) -> ChatRequestOptions {
    var options = ChatRequestOptions(model: "m", systemPrompt: golden.systemPrompt, temperature: 0.25, maxTokens: 64)
    options.serverKind = kind == "nil" ? nil : InferenceServerKind(rawValue: kind)
    options.tools = golden.tools
    options.omitsTools = golden.omitsTools
    return options
}

private func goldenBytes(_ golden: NativeGoldenCase, kind: String, usage: Bool) throws -> String {
    let options = options(for: golden, kind: kind)
    let body = ChatClient.buildRequestBody(messages: golden.history, options: options, includeUsage: usage)
    let data = golden.sendsTools
        ? try ChatClient.encodeBody(body, options: options)
        : try JSONSerialization.data(withJSONObject: body, options: [.sortedKeys])
    return String(decoding: data, as: UTF8.self)
}

/// Every row, in the fixture's order.
private func nativeGoldenRows() throws -> [String] {
    var rows: [String] = []
    for golden in nativeGoldenCases {
        for kind in nativeGoldenKinds {
            for usage in [false, true] {
                rows.append("\(golden.name)|\(kind)|\(usage)|\(try goldenBytes(golden, kind: kind, usage: usage))")
            }
        }
    }
    return rows
}

@Suite struct NativeToolGoldenTests {
    @Test func everyNativeBodyIsByteIdentical() throws {
        let golden = nativeToolGoldenBodies.split(separator: "\n").map(String.init)
        let rows = try nativeGoldenRows()
        #expect(golden.count == 196)
        #expect(rows.count == golden.count)
        for (row, expected) in zip(rows, golden) {
            #expect(row == expected)
        }
    }

    @Test func theFourCasesTheDesignNamesAreCovered() throws {
        let golden = nativeToolGoldenBodies.split(separator: "\n").map(String.init)
        // Row prefixes, not contents: a body must say what its case claims.
        let withTools = try #require(golden.first { $0.hasPrefix("tools|nil|false|") })
        #expect(withTools.contains(#""tools":[{"function":{"description":"#))
        let replayed = try #require(golden.first { $0.hasPrefix("replay-closed|nil|false|") })
        #expect(replayed.contains(#""tool_call_id":"call_1""#) && replayed.contains(#""tool_calls":["#))
        let flattened = try #require(golden.first { $0.hasPrefix("flattened-omitted|nil|false|") })
        #expect(flattened.contains("[Earlier tool call: srv.echo(") && !flattened.contains(#""tool_calls""#))
        let cap = try #require(golden.first { $0.hasPrefix("answer-now-cap|nil|false|") })
        #expect(cap.contains(ToolResultText.answerNow) && !cap.contains(#""tools""#))
    }

    @Test func flattenedBodiesAreWrittenAsBefore() throws {
        for golden in nativeGoldenCases where !golden.sendsTools {
            let options = options(for: golden, kind: "nil")
            let body = ChatClient.buildRequestBody(messages: golden.history, options: options, includeUsage: true)
            #expect(try ChatClient.encodeBody(body, options: options) == JSONSerialization.data(withJSONObject: body), "\(golden.name)")
        }
    }
}

